kit.score(function (S, T) {
  S.tempo(96, { t0: 0 });
  S.program('pad', 'pad', { rev: 0.45, gain: -6 });
  S.program('keys', 'ep', { rev: 0.3, gain: -4 });

  S.chord('pad', ['D3', 'A3', 'E4'], { t: 0, dur: 8, vel: 28 });
  S.chord('pad', ['B2', 'F#3', 'D4'], { t: 8.5, dur: 7.5, vel: 28 });
  S.chord('pad', ['G3', 'D4', 'A4'], { t: 16.5, dur: 7.0, vel: 30 });

  // Exact interaction frame effects
  S.fx('click', T['sidebar-collapse'] + 1.35, { vel: 52 });
  S.fx('whoosh', T['sidebar-collapse'] + 1.5, { dur: 0.45, vel: 42 });

  S.fx('pop', T['rail-swap'] + 1.05, { vel: 44 });
  S.fx('pop', T['rail-swap'] + 2.65, { vel: 44 });

  S.fx('click', T['mobile-drawer'] + 0.95, { vel: 52 });
  S.fx('whoosh', T['mobile-drawer'] + 1.05, { dur: 0.4, vel: 40 });
  S.fx('click', T['mobile-drawer'] + 3.05, { vel: 50 });

  S.fx('click', T['answer-feedback'] + 0.9, { vel: 50 });
  S.fx('click', T['answer-feedback'] + 1.6, { vel: 54 });
  S.fx('ding', T['answer-feedback'] + 2.85, { vel: 58 });

  S.fx('pop', T['reduced-motion'] + 0.85, { vel: 42 });
  S.fx('chime', T['reduced-motion'] + 2.75, { vel: 54 });

  S.master({ gain: -8, fadeOut: 1.2 });
});
